import{_ as i,C as o,o as e,c as r,a2 as a,b as d,w as s,a as n,E as u,a3 as p}from"./chunks/framework.BC3NdntU.js";const A=JSON.parse('{"title":"5.4 Vite 与 esbuild","description":"","frontmatter":{},"headers":[],"relativePath":"卷五-构建与工程化/5.4-Vite与esbuild.md","filePath":"卷五-构建与工程化/5.4-Vite与esbuild.md","lastUpdated":1788786153000}'),h={name:"卷五-构建与工程化/5.4-Vite与esbuild.md"};function b(c,t,E,g,k,m){const l=o("Mermaid");return e(),r("div",null,[t[1]||(t[1]=a('<h1 id="_5-4-vite-与-esbuild" tabindex="-1">5.4 Vite 与 esbuild <a class="header-anchor" href="#_5-4-vite-与-esbuild" aria-label="Permalink to &quot;5.4 Vite 与 esbuild&quot;">​</a></h1><blockquote><p>卷:卷五 · 构建与工程化 难度:⭐⭐ 进阶 | 阅读时间:25min | 状态:进行中</p></blockquote><hr><h2 id="引言-vite-为什么-一启动就能开发" tabindex="-1">引言:Vite 为什么&quot;一启动就能开发&quot; <a class="header-anchor" href="#引言-vite-为什么-一启动就能开发" aria-label="Permalink to &quot;引言:Vite 为什么&quot;一启动就能开发&quot;&quot;">​</a></h2><p>webpack 的思路是&quot;先把所有模块打包,再启动服务器&quot;——项目越大启动越慢。Vite 反其道而行:<strong>开发期不打包</strong>,靠浏览器原生 ESM + 按需编译,快得惊人。</p><hr><h2 id="一、vite-的双引擎-开发用-esbuild-构建用-rollup" tabindex="-1">一、Vite 的双引擎:开发用 esbuild,构建用 Rollup <a class="header-anchor" href="#一、vite-的双引擎-开发用-esbuild-构建用-rollup" aria-label="Permalink to &quot;一、Vite 的双引擎:开发用 esbuild,构建用 Rollup&quot;">​</a></h2>',7)),(e(),d(p,null,{default:s(()=>[u(l,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TB%0A%20%20%20%20subgraph%20%E5%BC%80%E5%8F%91%20dev%0A%20%20%20%20A%5B%E8%AF%B7%E6%B1%82%E6%A8%A1%E5%9D%97%5D%20--%3E%20B%5Bnative%20ESM%20%E7%9B%B4%E6%8E%A5%E5%8A%A0%E8%BD%BD%5D%0A%20%20%20%20B%20--%3E%20C%7B%E6%B5%8F%E8%A7%88%E5%99%A8%E8%AF%B7%E6%B1%82%E6%9F%90%E4%B8%AA%E6%A8%A1%E5%9D%97%7D%0A%20%20%20%20C%20--%3E%7C%E6%8C%89%E9%9C%80%7C%20D%5Besbuild%20%E7%9E%AC%E7%BC%96%E8%AF%91%E8%AF%A5%E6%A8%A1%E5%9D%97%E8%BF%94%E5%9B%9E%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20%E6%9E%84%E5%BB%BA%20build%0A%20%20%20%20E%5B%E5%85%A8%E9%87%8F%E4%BE%9D%E8%B5%96%E5%88%86%E6%9E%90%5D%20--%3E%20F%5BRollup%20%E6%89%93%E5%8C%85%5D%0A%20%20%20%20F%20--%3E%20G%5B%E4%BA%A7%E7%89%A9%20%2B%20%E6%A0%91%E6%91%87%20%2B%20%E5%88%86%E5%8C%85%5D%0A%20%20%20%20end%0A"})]),fallback:s(()=>[...t[0]||(t[0]=[n(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a(`<table tabindex="0"><thead><tr><th>阶段</th><th>引擎</th><th>为什么</th></tr></thead><tbody><tr><td><strong>开发</strong></td><td>esbuild(预构建)+ 原生 ESM</td><td>快,不打包,按需</td></tr><tr><td><strong>构建</strong></td><td><strong>Rollup</strong></td><td>树摇好、产物干净、适合产线</td></tr></tbody></table><hr><h2 id="二、三个关键机制" tabindex="-1">二、三个关键机制 <a class="header-anchor" href="#二、三个关键机制" aria-label="Permalink to &quot;二、三个关键机制&quot;">​</a></h2><h3 id="_1-依赖预构建-预打包" tabindex="-1">1. 依赖预构建(预打包) <a class="header-anchor" href="#_1-依赖预构建-预打包" aria-label="Permalink to &quot;1. 依赖预构建(预打包)&quot;">​</a></h3><p><code>node_modules</code> 里的库(CJS 格式、几十上百个文件)如果按原生 ESM 逐个请求会爆炸。Vite 启动时用 <strong>esbuild 预构建</strong>:</p><ul><li>把 CJS 转 ESM</li><li>把分散小文件<strong>合并成单个</strong>依赖(如 <code>lodash-es</code> 几百个模块 → 一个)</li></ul><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">✓</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 预构建依赖:vue,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> axios,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lodash-es</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">  # 启动日志里的那行</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-按需编译-秒级-hmr" tabindex="-1">2. 按需编译 + 秒级 HMR <a class="header-anchor" href="#_2-按需编译-秒级-hmr" aria-label="Permalink to &quot;2. 按需编译 + 秒级 HMR&quot;">​</a></h3><ul><li>浏览器<strong>请求到哪个文件</strong>,esbuild 才现编译哪个(不碰没访问的模块)</li><li>HMR:改哪个文件,只<strong>失效那一条链</strong>,毫秒级替换,<strong>状态不丢</strong></li></ul><h3 id="_3-构建时走-rollup" tabindex="-1">3. 构建时走 Rollup <a class="header-anchor" href="#_3-构建时走-rollup" aria-label="Permalink to &quot;3. 构建时走 Rollup&quot;">​</a></h3><p>生产构建追求<strong>最优产物</strong>(树摇、分包、兼容),用 Rollup 更稳——esbuild 虽快但&quot;产物极致优化&quot;不如 Rollup 成熟。</p><hr><h2 id="三、为什么-esbuild-这么快" tabindex="-1">三、为什么 esbuild 这么快 <a class="header-anchor" href="#三、为什么-esbuild-这么快" aria-label="Permalink to &quot;三、为什么 esbuild 这么快&quot;">​</a></h2><p>(呼应 5.2):esbuild 用 <strong>Go</strong> 实现,编译为原生机器码、内部并行、复用 AST、不引导 JS 运行时,所以比 JS 写的打包/转译器快 1~2 个数量级。</p><hr><h2 id="四、vite-vs-webpack-一张表选型" tabindex="-1">四、Vite vs webpack:一张表选型 <a class="header-anchor" href="#四、vite-vs-webpack-一张表选型" aria-label="Permalink to &quot;四、Vite vs webpack:一张表选型&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Vite</th><th>webpack</th></tr></thead><tbody><tr><td>开发启动</td><td><strong>秒级</strong>(不打包)</td><td>秒到分钟(全量打包)</td></tr><tr><td>HMR</td><td>极快(按需失效)</td><td>较慢(随项目变大)</td></tr><tr><td>构建引擎</td><td>esbuild(dev)+ Rollup(build)</td><td>自研 tapable 体系</td></tr><tr><td>生态/插件</td><td>快速成长,基于 Rollup 生态</td><td><strong>最全最成熟</strong></td></tr><tr><td>适用</td><td>新项目、现代浏览器、SDK/库</td><td>复杂/老项目、深度定制、兼容性要求高</td></tr></tbody></table><blockquote><p>趋势:新项目默认 Vite;存量复杂项目继续 webpack;底层 Rust 重写的 Rolldown 正在成为 Vite 未来的构建内核(见 5.6)。</p></blockquote><hr><h2 id="五、小结" tabindex="-1">五、小结 <a class="header-anchor" href="#五、小结" aria-label="Permalink to &quot;五、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Vite 双引擎:dev 用 esbuild(预构建 + 不打包 + 按需编译),build 用 Rollup</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三机制:依赖预构建(CJS→ESM,合并小模块)/ 按需编译 + 秒级 HMR / 构建走 Rollup</span></span>
<span class="line"><span>对比:Vite 开发快、适合新项目;webpack 生态全、适合复杂/存量项目</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><hr><h2 id="六、面试题" tabindex="-1">六、面试题 <a class="header-anchor" href="#六、面试题" aria-label="Permalink to &quot;六、面试题&quot;">​</a></h2><p><strong>Q1:Vite 为什么开发环境&quot;几乎秒开&quot;,webpack 却越来越慢?</strong></p><p>Vite 开发期<strong>不打包</strong>:用浏览器原生 ESM,请求到哪个模块才用 esbuild 现编译哪个(按需);webpack 要先把<strong>所有模块打成一个(或几个)包</strong>再启动,项目越大、模块越多越慢。这是&quot;按需 vs 全量&quot;的差异。</p><p><strong>Q2:Vite 的&quot;依赖预构建&quot;解决什么问题?</strong></p><p><code>node_modules</code> 里的第三方库常是 CJS、且拆成海量小文件。预构建用 esbuild 把它们① <strong>CJS 转 ESM</strong>、② <strong>合并成大模块</strong>,避免浏览器发起成千上万个请求,兼顾&quot;不打包&quot;与&quot;加载效率&quot;。</p><p><strong>Q3:为什么 Vite 开发用 esbuild、构建却用 Rollup?</strong></p><p>esbuild 快,但作为构建器<strong>产物极致优化</strong>(精细的 tree-shaking、分包控制、兼容处理)不如 Rollup 成熟稳定;生产构建要的是&quot;最优产物&quot;而非&quot;最快构建&quot;,所以分工:开发求快用 esbuild,构建求优用 Rollup。</p><hr><p>📎 参考:Vite 官方文档、esbuild 官网、Rollup 文档</p>`,31))])}const _=i(h,[["render",b]]);export{A as __pageData,_ as default};
